toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500, 1)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents and freeOverCents", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line("a", 200, 1)], 3000)).toBe(500);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line("a", 200, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line("a", 200, 1)], 6000)).toBe(0);
    });

    it("returns flat rate when no threshold is set", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line("a", 200, 1)], 100000)).toBe(799);
    });

    it("returns 0 for empty cart even with flat rate", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 for empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([], 100)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 100.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            99.9,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 300 },
        { upToGrams: 500, costCents: 200 },   // unsorted on purpose — constructor sorts
        { upToGrams: 5000, costCents: 800 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(calc.computeShippingCents([line("a", undefined, 3)], 1000)).toBe(0);
    });

    it("selects first bracket when weight <= lowest upToGrams", () => {
      // weight = 300g, fits in 500g bracket → 200
      expect(calc.computeShippingCents([line("a", 300, 1)], 1000)).toBe(200);
    });

    it("selects exact bracket boundary", () => {
      // weight = 500g exactly → 200 (500g bracket)
      expect(calc.computeShippingCents([line("a", 500, 1)], 1000)).toBe(200);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      // weight = 501g → 1000g bracket → 300
      expect(calc.computeShippingCents([line("a", 501, 1)], 1000)).toBe(300);
    });

    it("selects highest bracket at its boundary", () => {
      // weight = 5000g → 5000g bracket → 800
      expect(calc.computeShippingCents([line("a", 2500, 2)], 1000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight = 6000g > 5000g → overflow 1500
      expect(calc.computeShippingCents([line("a", 3000, 2)], 1000)).toBe(1500);
    });

    it("falls back to heaviest bracket when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 200 },
        { upToGrams: 1000, costCents: 400 },
      ]);
      // weight = 2000g > 1000g, no overflow → heaviest bracket cost = 400
      expect(
        noOverflow.computeShippingCents([line("a", 2000, 1)], 1000),
      ).toBe(400);
    });

    it("sums weight across multiple lines", () => {
      // 200*2 + 400*1 = 800g → 1000g bracket → 300
      const lines = [line("a", 200, 2), line("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

