+      // weight = 300g, fits in 500g bracket → 200
+      expect(calc.computeShippingCents([line("a", 300, 1)], 1000)).toBe(200);
+    });
+
+    it("selects exact bracket boundary", () => {
+      // weight = 500g exactly → 200 (500g bracket)
+      expect(calc.computeShippingCents([line("a", 500, 1)], 1000)).toBe(200);
+    });
+
+    it("moves to next bracket when weight exceeds boundary", () => {
+      // weight = 501g → 1000g bracket → 300
+      expect(calc.computeShippingCents([line("a", 501, 1)], 1000)).toBe(300);
+    });
+
+    it("selects highest bracket at its boundary", () => {
+      // weight = 5000g → 5000g bracket → 800
+      expect(calc.computeShippingCents([line("a", 2500, 2)], 1000)).toBe(800);
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      // weight = 6000g > 5000g → overflow 1500
+      expect(calc.computeShippingCents([line("a", 3000, 2)], 1000)).toBe(1500);
+    });
+
+    it("falls back to heaviest bracket when no overflow specified", () => {
+      const noOverflow = new WeightBasedShippingCalculator([
+        { upToGrams: 500, costCents: 200 },
+        { upToGrams: 1000, costCents: 400 },
+      ]);
+      // weight = 2000g > 1000g, no overflow → heaviest bracket cost = 400
+      expect(
+        noOverflow.computeShippingCents([line("a", 2000, 1)], 1000),
+      ).toBe(400);
+    });
+
+    it("sums weight across multiple lines", () => {
+      // 200*2 + 400*1 = 800g → 1000g bracket → 300
+      const lines = [line("a", 200, 2), line("b", 400, 1)];
+      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
+    });
+  });
+});
